import{_ as t,o,c as a,ag as r}from"./chunks/framework.BIas3y6W.js";const m=JSON.parse('{"title":"Week 4 — Undo, Compare, Explain","description":"","frontmatter":{"source":"weeks/04-undo-compare-explain/README.md"},"headers":[],"relativePath":"weeks/04-undo-compare-explain/index.md","filePath":"weeks/04-undo-compare-explain/index.md"}'),s={name:"weeks/04-undo-compare-explain/index.md"};function n(i,e,h,d,l,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="week-4--undo-compare-explain" tabindex="-1">Week 4 — Undo, Compare, Explain <a class="header-anchor" href="#week-4--undo-compare-explain" aria-label="Permalink to &quot;Week 4 — Undo, Compare, Explain&quot;">​</a></h1><blockquote><p>Save points only matter if you use them: break your game and bring it back, judge two AIs against your own check, and explain and test code you didn&#39;t type.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (≤30 min)</td><td>Your game&#39;s last commit is a working version · you can sign in to <strong>two</strong> chat assistants · read this page · before Studio B, pick the function in your game you&#39;ll test (<a href="./lab.html#part-b2--your-first-automated-test-35-min">lab Part B2</a>)</td></tr><tr><td><strong>Studio A</strong></td><td>Break your game on purpose and restore it from its History, then send the same prompt to two AI models and judge both against your own &quot;Done when&quot;</td></tr><tr><td><strong>Studio B</strong></td><td>Explain a classmate&#39;s function (🔴 AI off), write your <strong>first automated test</strong> for a function in your game and run it with <code>node --test</code>, a prompt makeover workshop, exit ticket (🔴 AI off)</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before)</td><td>One more feature in 3+ commits, checked first and taught back · your game using the tested function, <code>npm test</code> passing · a restore drill · <code>prompt-makeover.md</code> · <code>PROMPTS.md</code> · on Canvas: your reflection. Full list: <a href="./homework.html#deliverables-checklist">deliverables checklist</a></td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: the break, the comparison, the feature, testing one makeover prompt · 🟡 AI limited: the automated test (the AI may explain an error; you write the tests) · 🔴 AI off: the restore drill, the peer swap, your own test, the makeover rewrites, teach-backs, the exit ticket and the reflection</td></tr><tr><td><strong>Must read</strong></td><td>This page, the <a href="./lab.html">lab</a>, the <a href="./homework.html">homework</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./../03-prompting-and-save-points/game-menu.html">Game menu</a> · <a href="./../../resources/git-cheatsheet.html">Git Cheat Sheet</a> · <a href="./../../setup/codespaces.html">GitHub Codespaces</a> · <a href="./../../resources/prompt-patterns.html">Prompt Patterns</a> · <a href="./../../resources/troubleshooting.html">Troubleshooting</a> · <a href="./../../resources/glossary.html">Glossary</a> · <a href="./../../TOOLS.html">Tool Handout</a> · <a href="./../../resources/accessibility.html">Screen reader and keyboard guide</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>You can restore an earlier version of a file from its History, and <code>npm test</code> runs at least one passing test in your home-page repository. Week 5 starts a new project with the same commit habits, and from week 6 its checks are tests like this one</td></tr><tr><td><strong>Time</strong></td><td>Studios 2 × 75 min · outside about 6 h (prep up to 30 min, homework core about 3 h, project time about 2 h, <code>PROMPTS.md</code> and reflection about 30 min); stretch is optional</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Restore an earlier working version of a file from its History, as a new commit, and explain why nothing is lost.</li><li>Judge two AI models&#39; answers to the same prompt against a &quot;Done when&quot; you wrote first.</li><li>Explain a function in someone else&#39;s code without AI.</li><li>Rewrite a weak prompt in four parts that someone else could check in a minute.</li><li>Test a pure function from your game with Node&#39;s built-in test runner, and watch the test fail and pass.</li><li>Move a function into a JavaScript module and use it from your game.</li><li>Build a feature with <strong>check first</strong> and <strong>teach back</strong>.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><ul><li>☐ Your game&#39;s <strong>last commit is a working version</strong>. If your last step is half-done, finish it or restore it before Studio A.</li><li>☐ You can sign in to <strong>two</strong> chat assistants from the <a href="./../../TOOLS.html">Tool Handout</a>, with <a href="./../../setup/privacy-settings.html">privacy settings</a> done. Under 18? Your instructor will say which second assistant to use.</li><li>☐ <strong>Before Studio B:</strong> pick the function in your game you&#39;ll test. The table in <a href="./lab.html#part-b2--your-first-automated-test-35-min">lab Part B2</a> suggests one for each game. Check that you can still open a Codespace (<a href="./../../setup/codespaces.html">GitHub Codespaces</a>; you did it once in the week 0 setup).</li></ul><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap of week 3&#39;s most-missed exit-ticket question · concept talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-04.html" target="_blank" rel="noreferrer">slides</a>): going back, comparing models, tests · live demo of a restore and a comparison · lab: break it and go back, two models one prompt · checkpoint share</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Show and tell · lab: the peer explanation swap (🔴 AI off), your first automated test in a Codespace, the prompt makeover workshop · exit ticket (🔴 AI off)</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="./lab.html">Lab</a></td><td>Step-by-step, both studios (must read)</td></tr><tr><td><a href="./homework.html">Homework</a></td><td>Core and stretch, with the deliverables checklist (must read)</td></tr><tr><td><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-04.html" target="_blank" rel="noreferrer">Slides</a></td><td>Studio A&#39;s concept talk, with the slides for Studio B&#39;s mini-lessons</td></tr><tr><td><a href="./../03-prompting-and-save-points/game-menu.html">Game menu</a></td><td>Your game&#39;s sample plan and the ways to break it on purpose</td></tr><tr><td><a href="./../../setup/codespaces.html">GitHub Codespaces</a></td><td>Opening, using and stopping a Codespace</td></tr><tr><td><a href="./../../resources/without-ai-skills.html">Six skills you must show without AI</a></td><td>Skills 2 (explain a function) and 4 (revert a bad commit) start this week</td></tr></tbody></table><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p>If you are working through this week on your own, read this section, then do the <a href="./lab.html">lab</a>. The <a href="./../../resources/self-paced.html">self-paced path</a> says what to do instead of the pair activities.</p><h3 id="going-back-is-calm-not-scary" tabindex="-1">Going back is calm, not scary <a class="header-anchor" href="#going-back-is-calm-not-scary" aria-label="Permalink to &quot;Going back is calm, not scary&quot;">​</a></h3><p>Last week you made a save point after every working step. This week you use one. You open the file&#39;s <strong>History</strong> on github.com, find the last commit that worked, and commit that version again. Nothing is erased: the broken commit stays in the history, with the restore on top. That&#39;s what <code>git revert</code> does, and you&#39;ll type the real command in week 8. Going back to a working version is one of the <a href="./../../resources/without-ai-skills.html">six skills you must show without AI</a>, because AI tools can break things fast: in 2025 an AI agent deleted a company&#39;s production database, then wrongly claimed it couldn&#39;t be rolled back (<a href="https://fortune.com/2025/07/23/ai-coding-tool-replit-wiped-database-called-it-a-catastrophic-failure/" target="_blank" rel="noreferrer">Fortune</a>).</p><h3 id="two-models-one-prompt" tabindex="-1">Two models, one prompt <a class="header-anchor" href="#two-models-one-prompt" aria-label="Permalink to &quot;Two models, one prompt&quot;">​</a></h3><p>Different assistants give different answers to the same prompt. You judge them against your own &quot;Done when&quot;, written before you look, not by which looks cooler, and not by what the AI claims. Which model &quot;wins&quot; changes from month to month; being the judge is the skill that lasts.</p><h3 id="if-you-can-explain-it-you-own-it" tabindex="-1">If you can explain it, you own it <a class="header-anchor" href="#if-you-can-explain-it-you-own-it" aria-label="Permalink to &quot;If you can explain it, you own it&quot;">​</a></h3><p>In the peer explanation swap you explain one function in a classmate&#39;s game, with 🔴 AI off. That&#39;s the golden rule from last week&#39;s reading in practice, and it&#39;s how the course checks understanding: in the oral walkthroughs from week 8, you explain your own code without AI.</p><h3 id="writing-the-prompt-is-the-skill" tabindex="-1">Writing the prompt is the skill <a class="header-anchor" href="#writing-the-prompt-is-the-skill" aria-label="Permalink to &quot;Writing the prompt is the skill&quot;">​</a></h3><p>The prompt makeover asks you to rewrite four weak prompts yourself, without AI. A good rewrite has one goal, puts in the context the AI can&#39;t see, protects what already works, and has a &quot;Done when&quot; someone else could check in under a minute.</p><h3 id="a-test-is-a-check-that-runs-itself" tabindex="-1">A test is a check that runs itself <a class="header-anchor" href="#a-test-is-a-check-that-runs-itself" aria-label="Permalink to &quot;A test is a check that runs itself&quot;">​</a></h3><p>So far your checks were things you tried by hand. An <strong><a href="./../../resources/glossary.html#test-manual-and-automated">automated test</a></strong> is code that checks your code, in a second, every time you run it. The easiest code to test is a <strong><a href="./../../resources/glossary.html#pure-function">pure function</a></strong>: it uses only its inputs and returns a result, with no page, timers, random numbers or storage. You&#39;ll move one from your game (an average, a score rule, a collision check) into its own file, a <strong><a href="./../../resources/glossary.html#module">module</a></strong>, and test it with the runner built into <strong><a href="./../../resources/glossary.html#nodejs">Node.js</a></strong>, which runs JavaScript outside the browser. Like <code>pytest</code>, with nothing to install.</p><p>Two rules come with tests. <strong>Watch it fail:</strong> a test you&#39;ve never seen fail might not check anything, so you break the code on purpose once (<a href="./../../resources/glossary.html#redgreen-testing">red/green testing</a>). <strong>Never change a test just to make it pass:</strong> if a test seems wrong, decide yourself, and write down why. From week 6, <strong>check first</strong> means writing a test like this <em>before</em> asking for the code.</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><ul><li><strong>In Studio B:</strong> the peer explanation swap. You explain one function in a classmate&#39;s game, with 🔴 AI off, and they confirm or correct you.</li><li><strong>At the end of Studio B:</strong> the Week 4 exit ticket (🔴 AI off, scored for completion). Expect: how to get back to a working version; when one function in your game runs; what your first test checks and what change would make it fail; one question about the home page you published in week 2.</li></ul><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p>About 5 hours of core work plus the journal; details on the <a href="./homework.html">homework page</a>. <strong>Project time:</strong> one more feature in 3+ save points, &quot;Done when&quot; first, a teach-back before each commit. <strong>Homework:</strong> a restore drill (🔴 AI off), the rest of the prompt makeover (🔴 AI off for the rewrites), and making your game use the tested function. <strong>Journal:</strong> <code>PROMPTS.md</code>; the reflection on Canvas (🔴 AI off). <strong>Stretch:</strong> a test written before the code, a second feature or a second tested function.</p><p>Graded on effort and completion of the core tier (<a href="./../../assessment/rubrics.html#weekly-labs-and-homework">rubric</a>).</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td>Your main assistant is down or you hit a limit</td><td>Use a fallback from the <a href="./../../TOOLS.html">Tool Handout</a>, pasting your current <code>game/index.html</code> (<a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">out of credits</a>)</td></tr><tr><td>Only one assistant works</td><td>Compare two fresh chats in the same assistant</td></tr><tr><td>Codespaces won&#39;t start, or you&#39;re out of hours</td><td>Run the test with Node.js on your own computer (<a href="./../../setup/local-setup.html">local setup</a>), or watch a neighbor&#39;s today and run yours at home</td></tr><tr><td>GitHub is down</td><td>Peer swap and makeover first; restore and test later with the lab steps</td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li><a href="./../../resources/git-cheatsheet.html#revert-vs-reset">Git Cheat Sheet: revert vs reset</a>: why the course only ever undoes with a new commit.</li><li><a href="./../../resources/prompt-patterns.html">Prompt Patterns</a>: the check-first test prompt (pattern 16) and &quot;Compare two approaches&quot; (pattern 10).</li><li><a href="https://nodejs.org/api/test.html" target="_blank" rel="noreferrer">Node.js test runner documentation</a>: everything <code>node --test</code> can do.</li><li>The <a href="./../../resources/reading-list.html">Reading List</a>.</li></ul>',35)])])}const p=t(s,[["render",n]]);export{m as __pageData,p as default};
